<script setup lang="ts">import { computed,onMounted,ref } from 'vue'; import { useRoute } from 'vue-router'; import LoadingState from '../components/LoadingState.vue'; import QuestionCard from '../components/QuestionCard.vue'; import { useExamStore } from '../stores/exam'; import { allQuestions } from '../services/testLoader'; import type { ToeicTest } from '../types/exam'; const route=useRoute(),store=useExamStore(),testId=String(route.params.testId),test=ref<ToeicTest>(),filter=ref('all'); onMounted(async()=>{try{test.value=await store.ensureTest(testId)}catch{}}); const result=computed(()=>store.latestResults[testId]); const questions=computed(()=>{if(!test.value||!result.value)return[];return allQuestions(test.value).filter(q=>filter.value==='wrong'?result.value?.wrongQuestions.includes(q.id):filter.value==='correct'?result.value?.answers[q.id]===q.answer:filter.value==='unanswered'?result.value?.unansweredQuestions.includes(q.id):true)})</script>
<template><div class="page"><LoadingState :loading="store.loading" :error="store.error"/><template v-if="test&&result"><div class="workspace-header"><div><p class="eyebrow">Answer review</p><h1>{{ questions.length }} questions</h1></div><RouterLink class="button" :to="`/test/${testId}/result`">Back to result</RouterLink></div><div class="filter-tabs"><button v-for="item in ['all','wrong','correct','unanswered']" :key="item" :class="{active:filter===item}" @click="filter=item">{{ item }}</button></div><div class="questions-stack"><QuestionCard v-for="question in questions" :key="question.id" :question="question" :model-value="result.answers[question.id]" reveal show-transcript/></div><div v-if="!questions.length" class="empty-state"><h2>No matching questions</h2><p>Try another review filter.</p></div></template></div></template>
